            "Both": "WITH first_query_result AS ( SELECT result->''score''->>''decisiondetails'' AS \\"decisiondetails\\", ilivemessageid AS \\"ILiveMessageID\\", vcmsgid AS \\"UniqueID\\", vcuniquetransid AS \\"UniqueID-DL\\", vcclassname AS \\"Class\\", dttrxntime  AS \\"Time\\", dobservationamount AS \\"Amount\\", score AS \\"Score\\", CASE WHEN result->>''status''=''Failed'' THEN ''false'' WHEN result->>''status''=''Success'' THEN ''true'' WHEN result->>''status'' IS NULL THEN CASE WHEN score > 0 THEN ''false'' WHEN score = 0 THEN ''true'' ELSE NULL END END AS \\"FRMPass\\", vcpayeraccountexternalid AS \\"Payer Account\\", vcpayeraddr AS \\"PayerVPA\\", vcpayeeaccountexternalid AS \\"Payee Account\\", vcpayeeaddr AS \\"PayeeVPA\\", vcpayeraccountexternalid AS \\"Payer Account-DL\\", vcpayeraddr AS \\"PayerVPA-DL\\", vcpayeeaccountexternalid AS \\"Payee Account-DL\\", vcpayeeaddr AS \\"PayeeVPA-DL\\", NULL AS \\"FailedRule\\", CAST(observations->''observations''->''payerVPA''->>''vpaName'' AS text) AS \\"PayerName\\", CAST(observations->''observations''->''payeeVPA''->>''vpaName'' AS text) AS \\"PayeeName\\", CAST(observations->''txn''->>''type'' AS text) AS \\"Txn Type\\", ipayeemccid AS \\"Payee MCC\\",CAST(observations->''txn''->''attribs''->''skip_processing'' AS int) AS \\"Skip Processing\\" FROM analytics.trans l JOIN masters.vpa vp ON (l.ipayeevpaid= vp.ivpaid or l.ipayervpaid=vp.ivpaid) WHERE vcuniquetransid =:msgid AND l.itenantid = :tenantid AND (vp.vcexternaladdressid = :vpaAddress) and vcclassname = :txnClass ) SELECT * FROM first_query_result UNION ALL (SELECT result->''score''->>''decisiondetails'' AS \\"decisiondetails\\", ilivemessageid AS \\"ILiveMessageID\\", vcmsgid AS \\"UniqueID\\", vcuniquetransid AS \\"UniqueID-DL\\", vcclassname AS \\"Class\\", dttrxntime AS \\"Time\\", dobservationamount AS \\"Amount\\", score AS \\"Score\\", CASE WHEN result->>''status'' = ''Failed'' THEN ''false'' WHEN result->>''status'' = ''Success'' THEN ''true'' WHE