t-DL\\", vcpayeeaddr AS \\"PayeeVPA-DL\\", NULL AS \\"FailedRule\\", CAST(observations->''observations''->''payerVPA''->>''vpaName'' AS text) AS \\"PayerName\\", CAST(observations->''observations''->''payeeVPA''->>''vpaName'' AS text) AS \\"PayeeName\\", CAST(observations->''txn''->>''type'' AS text) AS \\"Txn Type\\", ipayeemccid AS \\"Payee MCC\\", CAST(observations->''txn''->''attribs''->''skip_processing'' AS int) AS \\"Skip Processing\\" FROM analytics.trans l JOIN masters.vpa vp ON (l.ipayeevpaid= vp.ivpaid or l.ipayervpaid=vp.ivpaid) WHERE l.itenantid = :tenantid and vcclassname = :txnClass AND (vp.vcexternaladdressid = :vpaAddress) AND l.ilivemessageid < (SELECT \\"ILiveMessageID\\" FROM first_query_result) AND vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) and l.itenantid =  :tenantid ORDER BY l.ilivemessageid DESC LIMIT 20)"
