    "Initial":{
        "All":{
            "All":{
                "All":"select ilivemessageid as \\"ILiveMessageID\\", vcmsgid AS \\"UniqueID\\", vcuniquetransid AS \\"UniqueID-DL\\", vcclassname as \\"Class\\", dttrxntime as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\", case when json_extract_scalar(result, ''$.status'') = ''Failed'' then ''false'' when json_extract_scalar(result, ''$.status'') = ''Success'' then ''true'' when json_extract_scalar(result, ''$.status'') IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0 THEN ''true'' else NULL end end  as \\"FRMPass\\", vcpayeraccountexternalid AS \\"Payer Account\\", vcpayeraddr AS \\"PayerVPA\\", vcpayeeaccountexternalid AS \\"Payee Account\\", vcpayeeaddr AS \\"PayeeVPA\\", vcpayeraccountexternalid AS \\"Payer Account-DL\\", vcpayeraddr AS \\"PayerVPA-DL\\", vcpayeeaccountexternalid AS \\"Payee Account-DL\\", vcpayeeaddr AS \\"PayeeVPA-DL\\", null as \\"FailedRule\\", json_extract_scalar(observations, ''$.observations.payerVPA.vpaName'')  as \\"PayerName\\",  json_extract_scalar(observations, ''$.observations.payeeVPA.vpaName'') as  \\"PayeeName\\", json_extract(observations, ''$.txn.type'')  as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",json_extract_scalar(observations, ''$.txn.attribs.skip_processing'') as \\"Skip Processing\\" from t12refined.analytics.trans where vcclassname in (:allClasses) and itenantid = :tenantid ORDER BY dttrxntime desc LIMIT 1"
            }
        }
    },
    "Redirect":{
