            "Payer": "WITH first_query_result AS ( SELECT  json_extract(result, ''$.score.decisiondetails'') as \\"decisiondetails\\", ilivemessageid AS \\"ILiveMessageID\\", vcmsgid AS \\"UniqueID\\", vcuniquetransid AS \\"UniqueID-DL\\", vcclassname AS \\"Class\\", dttrxntime  AS \\"Time\\", dobservationamount AS \\"Amount\\", score AS \\"Score\\", case when json_extract_scalar(result, ''$.status'') = ''Failed'' then ''false'' when json_extract_scalar(result, ''$.status'') = ''Success'' then ''true'' when json_extract_scalar(result, ''$.status'') IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0 THEN ''true'' else NULL end end AS \\"FRMPass\\", vcpayeraccountexternalid AS \\"Payer Account\\", vcpayeraddr AS \\"PayerVPA\\", vcpayeeaccountexternalid AS \\"Payee Account\\", vcpayeeaddr AS \\"PayeeVPA\\", vcpayeraccountexternalid AS \\"Payer Account-DL\\", vcpayeraddr AS \\"PayerVPA-DL\\", vcpayeeaccountexternalid AS \\"Payee Account-DL\\", vcpayeeaddr AS \\"PayeeVPA-DL\\", NULL AS \\"FailedRule\\", json_extract_scalar(observations, ''$.observations.payerVPA.vpaName'')  AS \\"PayerName\\", json_extract_scalar(observations, ''$.observations.payeeVPA.vpaName'') AS \\"PayeeName\\", json_extract(observations, ''$.txn.type'') AS \\"Txn Type\\", ipayeemccid AS \\"Payee MCC\\",json_extract_scalar(observations, ''$.txn.attribs.skip_processing'') AS \\"Skip Processing\\" FROM t12refined.analytics.trans l  WHERE vcuniquetransid =:msgid AND vcclassname IN (:allClasses) AND l.itenantid = :tenantid AND ( l.vcpayeraccountexternalid = :vpaAddress)) SELECT * FROM first_query_result UNION ALL (SELECT  json_extract(result, ''$.score.decisiondetails'') as \\"decisiondetails\\", ilivemessageid AS \\"ILiveMessageID\\", vcmsgid AS \\"UniqueID\\", vcuniquetransid AS \\"UniqueID-DL\\", vcclassname AS \\"Class\\", dttrxntime AS \\"Time\\", dobservationamount AS \\"Amount\\", score AS \\"Score\\", case when json_extract_scalar(result, ''$.status'') = ''Failed'' then ''false'' when